/*
 * mathutil.h: the interface of mathutil.c. Do not edit this file.
 *
 * A header holds declarations (prototypes) that other .c files need in
 * order to call the functions defined in mathutil.c. The #ifndef /
 * #define / #endif lines are an include guard: the first time this file
 * is included MATHUTIL_H gets defined, so if it is included again in the
 * same .c file (directly or through another header) its contents are
 * skipped instead of being declared twice.
 */

#ifndef MATHUTIL_H
#define MATHUTIL_H

int add(int a, int b);
int multiply(int a, int b);

#endif
